#!/bin/bash
# v2 of side + back scenes (2026-11-09). Each run costs ChatGPT quota.
cd /c/timeoptic-content
K=kits/2026-11-09_prada-linea-rossa-sail
KEEP="Use the attached sunglasses exactly as they are: same shape, proportions, matte black frame, light-blue rubber inserts, dark blue mirror lenses, temples and hinges. Do not redesign, restyle, recolor or add any logo, text or extra parts. The glasses are the hero, sharp and in focus, with a realistic contact shadow and believable reflections of the scene."
STYLE="Square 1:1 luxury eyewear advertising photograph, cinematic, shot on a medium-format camera with a 100mm macro lens, shallow depth of field. Absolutely no text, no letters, no watermark, no logos anywhere in the image except the red temple bar that is already on the glasses. Leave calm dark negative space in the top 18% and bottom 14% of the frame for a logo overlay."
run () { codex exec -m gpt-5.6-luna -c model_reasoning_effort="low" -C "$PWD" --skip-git-repo-check -s workspace-write -i "$2" -o tmp/codex-$1.txt "Call the built-in image_gen tool exactly once with the prompt below, verbatim, using the attached image as the product reference. Do not rewrite the prompt, do not generate variants, do not inspect or edit the result. Reply with only the saved file path. PROMPT: $3" > tmp/codex-$1.log 2>&1; }
run side2 $K/layers/side.png "$STYLE The attached sunglasses in an exact side profile, temple running left to right, standing upright and stable on both temple tips and the lens edge on the glossy wet carbon-fibre deck of a racing sailboat at dusk, the whole pair fully in frame, centred, filling about 75% of the width. Camera low at the height of the temple, so the red bar with the white letters on the temple reads clearly and is perfectly sharp, letters unchanged. Behind, softly out of focus: a dark sail edge, backlit sea spray glittering orange, a deep navy ocean and a thin orange sunset line on the horizon. A few tiny water droplets on the matte black frame. A subtle soft reflection of the glasses on the wet deck, no readable letters in the reflection. Palette: deep navy, charcoal black, warm orange rim light along the top edge of the frame. Moody, premium, sporty. $KEEP" &
run back2 $K/layers/back.png "$STYLE The attached sunglasses seen from behind and slightly above, temples open toward the camera, resting on a neatly coiled dark-grey sailing rope on the wet deck of a racing sailboat at dusk. Important detail: the inner side of the frame is matte black with light-blue rubber pieces along the inner top corners and side shields exactly as in the attached photo; there is no red and no maroon anywhere on the inside of the frame. The light-blue inner rubber catches a soft cool light, the dark blue lenses show a faint reflection of the sunset. Background out of focus: a dark sail edge, navy ocean, spray and a low orange sunset glow. Palette: deep navy, charcoal black, light blue, warm orange rim light. Moody, premium, sporty. $KEEP" &
wait
